import java.io.*; import java.util.*; import org.apache.poi.hssf.usermodel.*; import org.apache.poi.ss.usermodel.*;
public class W25_Styles { public static void main(String[] a) throws Exception { try(HSSFWorkbook w=new HSSFWorkbook(new FileInputStream(a[0]))){ Sheet s=w.getSheet("Output"); Set<Short> fills=new HashSet<>(); Set<Short> fonts=new HashSet<>(); Set<String> fmts=new HashSet<>(); int borders=0,cells=0;
 for(Row r:s) for(Cell c:r){ cells++; CellStyle st=c.getCellStyle(); if(st.getFillPattern()!=FillPatternType.NO_FILL) fills.add(st.getFillForegroundColor()); fonts.add(st.getFontIndexAsInt()>0?(short)st.getFontIndexAsInt():0); fmts.add(st.getDataFormatString()); if(st.getBorderBottom()!=BorderStyle.NONE||st.getBorderTop()!=BorderStyle.NONE) borders++; }
 System.out.println("§STYLES Output cells="+cells+" distinctFills="+fills.size()+" distinctFonts="+fonts.size()+" numberFormats="+fmts.size()+" cellsWithBorders="+borders+" merged="+s.getNumMergedRegions()); }}}
